import {config} from './config.js';
import {modules,criteria,confidenceItems,knowledgeItems,attitudeItems,surveyVersion,stages,roleOptions,experienceOptions} from './content.js';
import {emptyWorkspace,validateWorkspace,completed,completionCount,storageKey} from './state.js';

const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let storageAvailable=true;
const store=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageAvailable=false;toast('Browser storage is unavailable. Export a backup to keep your work.');return false;}};
let workspace;
try{workspace=validateWorkspace(read(storageKey,emptyWorkspace()));}catch{workspace=emptyWorkspace();}
let prompts=[],resourceQuery='',stage='pre',dashboardToken='',stats=null,analyticsSent=new Set(),saveTimer;
let surveyDraft=read('acata.survey.draft.v1',{});
if(!surveyDraft||typeof surveyDraft!=='object'||Array.isArray(surveyDraft))surveyDraft={};
let service={available:false,research:{enabled:false}};
const view=$('#view');
const apiBase=config.apiBase.replace(/\/$/,'');
const originAllowed=!apiBase||/^https:\/\/[a-z0-9.-]+\.workers\.dev$/i.test(apiBase);
if(!originAllowed)console.error('The API must use an HTTPS workers.dev URL.');
const uid=()=>[...crypto.getRandomValues(new Uint8Array(24))].map(x=>x.toString(16).padStart(2,'0')).join('');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
async function api(path,{method='GET',body,token}={}){
 if(!apiBase||!originAllowed)throw new Error('The shared service is not connected yet. Local learning and backups are available.');
 const response=await fetch(apiBase+path,{method,credentials:'omit',cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(12000)});
 const data=await response.json().catch(()=>({error:'The service returned an unreadable response.'}));
 if(!response.ok)throw new Error(data.error||`Request failed (${response.status}).`);
 return data;
}
function save(){workspace.updatedAt=new Date().toISOString();store(storageKey,workspace);$$('[data-save-status]').forEach(el=>el.textContent=storageAvailable?'Saved in this browser · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'Storage unavailable · export to save');}
function heading(kicker,title,description){return `<div class="page-heading"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>`;}
function fileLink(name,label='Download template'){return `<a class="button secondary compact" href="./downloads/${e(name)}" download>${e(label)} <span aria-hidden="true">↓</span></a>`;}
function moduleCard(m){const done=completed(workspace,m.id);return `<a class="pathway-card" href="#module/${m.id}"><span class="module-icon ${m.color}" aria-hidden="true">${m.icon}</span><div class="module-copy"><div class="module-meta">MODULE ${m.number} · ${m.short.toUpperCase()}</div><h3>${m.title}</h3><p>${m.subtitle}</p></div>${done?'<span class="check-badge">✓ Complete</span>':'<span class="module-arrow" aria-hidden="true">↗</span>'}</a>`;}
function ring(){const count=completionCount(workspace),percent=count*20;return `<div class="ring-wrap"><svg class="progress-ring" viewBox="0 0 130 130" role="img" aria-label="${percent}% of modules complete"><circle cx="65" cy="65" r="54" fill="none" stroke="#edf0e7" stroke-width="7"/><circle cx="65" cy="65" r="54" fill="none" stroke="#6f8d61" stroke-width="7" stroke-linecap="round" stroke-dasharray="${percent*3.393} 339.3"/></svg><div class="ring-number">${percent}%<small>of your pathway</small></div></div>`;}
const heroArt=`<svg viewBox="0 0 400 310" fill="none" aria-hidden="true"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#a5bc9b" opacity=".22"/></pattern><linearGradient id="card" x1="90" y1="75" x2="290" y2="250" gradientUnits="userSpaceOnUse"><stop stop-color="#f0efda"/><stop offset="1" stop-color="#cdd8b9"/></linearGradient></defs><rect width="400" height="310" fill="url(#dots)"/><circle cx="210" cy="155" r="119" stroke="#789770" stroke-opacity=".3"/><circle cx="210" cy="155" r="88" stroke="#789770" stroke-opacity=".3" stroke-dasharray="3 8"/><path d="M84 206L327 81M73 96L325 233" stroke="#789770" stroke-opacity=".25"/><g transform="rotate(-9 209 160)"><rect x="132" y="67" width="158" height="197" rx="10" fill="#0b281f" opacity=".28"/><rect x="126" y="58" width="158" height="197" rx="9" fill="url(#card)"/><rect x="144" y="79" width="26" height="26" rx="5" fill="#254d3b"/><path d="M151 92l4 4 8-9" stroke="#f2eacb" stroke-width="2"/><text x="183" y="89" fill="#4c6447" font-family="sans-serif" font-size="7" letter-spacing="1.2">ITEM BLUEPRINT</text><text x="183" y="101" fill="#7c8b6b" font-family="sans-serif" font-size="6">DESIGNED WITH PURPOSE</text><path d="M144 120H265" stroke="#b7c4a3"/><text x="144" y="139" fill="#5e7454" font-family="sans-serif" font-size="6" letter-spacing="1">CONSTRUCT & EVIDENCE</text><path d="M144 150H251M144 159H228" stroke="#97ab86" stroke-width="3" stroke-linecap="round"/><rect x="144" y="178" width="121" height="47" rx="4" fill="#e4e9d4"/><path d="M154 189H208M154 199H245M154 209H231" stroke="#b4c1a1" stroke-width="2" stroke-linecap="round"/><circle cx="251" cy="239" r="5" stroke="#5d7b4e"/><path d="M248 239l2 2 4-4" stroke="#5d7b4e"/></g><g transform="rotate(7 313 118)"><rect x="264" y="94" width="107" height="48" rx="8" fill="#f1bd79"/><circle cx="284" cy="118" r="10" stroke="#967344"/><path d="M280 118l3 3 5-6" stroke="#614f32" stroke-width="1.5"/><text x="302" y="115" fill="#624b2d" font-family="sans-serif" font-size="7" font-weight="700">HUMAN REVIEW</text><text x="302" y="127" fill="#8b6c42" font-family="sans-serif" font-size="6">Always in the loop</text></g><g transform="rotate(-4 103 219)"><rect x="45" y="191" width="119" height="52" rx="8" fill="#45674d" stroke="#7f9c6b"/><text x="61" y="211" fill="#d5e1be" font-family="sans-serif" font-size="7" letter-spacing="1">EVIDENCE FIRST</text><path d="M61 226h6v-6h6v-9h6v15h6v-11h6v11h6v-17h6v17h6v-9h6v9h6v-14h6" stroke="#a4be82" stroke-width="1.5"/></g><circle cx="96" cy="97" r="16" fill="#355a42" stroke="#789266"/><path d="M96 87v20m-10-10h20m-17-7l14 14m-14 0l14-14" stroke="#cad9a9" stroke-width="1.2"/><circle cx="321" cy="220" r="4" fill="#eabe7c"/></svg>`;
function home(){
 const next=modules.find(m=>!completed(workspace,m.id))||modules[0];
 return `<div class="welcome-row"><div><h2>A space to learn. A place to return.</h2><p>Your companion to modernising item development with AI and LLMs.</p></div><span class="pill"><span class="dot"></span> ACATA 2026</span></div><section class="hero" aria-label="Workshop introduction"><div class="hero-copy"><div class="eyebrow">THE ITEM DEVELOPMENT LAB</div><h1>Better items.<br><em>Stronger evidence.</em></h1><p>Bring AI into your assessment workflow with clarity, care, and human judgment at every step.</p><a class="button" href="#module/${next.id}">${completionCount(workspace)?'Continue your pathway':'Begin your pathway'} <span aria-hidden="true">↗</span></a></div><div class="hero-art">${heroArt}<span class="art-caption">HUMAN JUDGMENT × AI ASSISTANCE</span></div></section><div class="stats-strip"><div class="strip-stat"><div class="stat-icon" aria-hidden="true">▤</div><div><strong>5 practical modules</strong><span>One connected development workflow</span></div></div><div class="strip-stat"><div class="stat-icon" aria-hidden="true">⊞</div><div><strong>Tools you can use</strong><span>Templates, prompts & worked examples</span></div></div><div class="strip-stat"><div class="stat-icon" aria-hidden="true">↗</div><div><strong>Built for your practice</strong><span>Return, reflect & track your progress</span></div></div></div><div class="section-header"><div><h2>Your learning pathway</h2><p>From a clear construct to an accountable item.</p></div><a class="text-link" href="#learn">Explore all modules ↗</a></div><div class="overview-grid"><section class="pathway-list" aria-label="Learning modules">${modules.map(moduleCard).join('')}</section><aside><div class="side-panel"><h3>A little progress, every visit.</h3>${ring()}<p>Pick up where you left off. Your checklist and notes save as you go.</p><a class="button secondary" href="#workspace">Open my workspace <span aria-hidden="true">↗</span></a><div class="progress-foot"><span>${completionCount(workspace)} of 5 modules complete</span><span>Self-paced</span></div></div><div class="research-teaser"><div class="mini-label">REFLECT & CONTRIBUTE</div><h3>Your experience<br>can inform the work.</h3><p>A workshop research survey exploring knowledge, confidence, and responsible AI practice.</p><a href="#survey">Preview the survey <span aria-hidden="true">↗</span></a></div></aside></div><section class="resource-banner"><div><h3>A practical toolkit. Ready when you are.</h3><p>Five editable templates and a complete Ohm’s law worked example set.</p></div><a class="button secondary" href="./downloads/participant-toolkit.zip" download>Download participant toolkit <span aria-hidden="true">↓</span></a></section>`;
}
function learn(){return heading('LEARNING PATHWAY','A deliberate process.<br>A defensible item.','Move through five connected stages. Each includes a short lesson, the original editable template, a worked example, and a checklist you can revisit anytime.')+`<div class="callout">This pathway is self-reported professional learning. Completing it does not certify an item, establish psychometric properties, or authorize operational use.</div><div class="pathway-list">${modules.map(moduleCard).join('')}</div><section class="panel prose" style="margin-top:24px"><h2>Keep the evidence question open.</h2><p>Blueprint → AI-assisted draft → independent review → metadata → audit trail. Across every stage, distinguish what you intended, what a reviewer observed, and what suitable response data actually demonstrate.</p><p>Begin with the supplied OHM-001 example, then use the same structure for a non-sensitive practice item in your own domain.</p><a class="button secondary" href="#example">Explore the worked example ↗</a></section>`;}
function field(m,key,label,hint){const value=workspace.fields[m.id]?.[key]||'';return `<label class="field">${e(label)}<textarea data-field="${m.id}:${key}" maxlength="12000" placeholder="${e(hint)}">${e(value)}</textarea><span class="field-help">${e(hint)}</span></label>`;}
function rubric(){return `<h3>16-criterion review worksheet</h3><p>Rate each criterion and give item-specific evidence. Use N/A with a reason. This tool deliberately does not calculate an average.</p><div class="callout warning">Critical defects block approval. A wrong key, serious content error, construct mismatch, or unacceptable fairness concern must be resolved.</div><div class="table-scroll"><table><caption>Source rubric · 4 Strong · 3 Acceptable · 2 Needs revision · 1 Major concern</caption><thead><tr><th scope="col">Criterion</th><th scope="col">Rating</th><th scope="col">Evidence / revision</th></tr></thead><tbody>${criteria.map(([name,hint],i)=>{const r=workspace.rubric[i]||{};return `<tr><th scope="row" class="rubric-name">${i+1}. ${e(name)}<small>${e(hint)}</small></th><td><select aria-label="Rating for ${e(name)}" data-rubric="${i}:rating">${[['','Not yet rated'],['4','4 · Strong'],['3','3 · Acceptable'],['2','2 · Needs revision'],['1','1 · Major concern'],['NA','N/A · explain why']].map(([v,l])=>`<option value="${v}" ${r.rating===v?'selected':''}>${l}</option>`).join('')}</select></td><td><textarea aria-label="Evidence for ${e(name)}" data-rubric="${i}:evidence" maxlength="12000">${e(r.evidence||'')}</textarea></td></tr>`;}).join('')}</tbody></table></div><div class="divider"></div><label class="field">Reviewer disposition<select data-workspace="disposition">${['','Approve for next review stage','Approve with minor edits','Revise and re-review','Hold or retire'].map(v=>`<option ${v===workspace.disposition?'selected':''} value="${e(v)}">${e(v||'Choose a disposition')}</option>`).join('')}</select></label><label class="field">Evidence, required action & reviewer role<textarea data-workspace="reviewSummary" maxlength="12000">${e(workspace.reviewSummary)}</textarea></label>`;}
function promptLibrary(){return `<div class="divider"></div><h3>Ten prompts. One human gate.</h3><p>Complete source prompts from the workshop pack. Replace every bracketed field. Review permitted data use before pasting anything into an AI system.</p>${prompts.length?prompts.map(p=>`<details><summary>${p.number}. ${e(p.title)}</summary><div class="details-body">${p.description?`<p>${e(p.description)}</p>`:''}<pre class="prompt" id="prompt-${p.number}">${e(p.body)}</pre><button class="button secondary compact" data-copy-prompt="${p.number}">Copy full prompt</button></div></details>`).join(''):'<p>Open the original Prompt Pack below to access all ten prompts.</p>'}`;}
function modulePage(id){const m=modules.find(m=>m.id===id);if(!m)return notFound();const index=modules.indexOf(m),next=modules[index+1];return `<div class="module-heading"><span class="module-icon ${m.color}" aria-hidden="true">${m.icon}</span><div><div class="eyebrow">MODULE ${m.number} / 05</div><h1>${m.title}</h1></div></div><div class="learning-grid"><article><section class="panel"><p>${m.intro}</p>${m.lessons.map(([title,points])=>`<section class="module-step"><h3>${title}</h3><ul>${points.map(p=>`<li>${p}</li>`).join('')}</ul></section>`).join('')}<div class="callout"><strong>From the worked example</strong><br>${m.exampleText}<br><a class="text-link" href="#example">Explore OHM-001 ↗</a></div><div class="button-row">${fileLink(m.file)}<a class="button secondary compact" href="./downloads/examples/${m.example}" download>Download worked example ↓</a></div></section><section class="panel"><div class="eyebrow">PUT IT INTO PRACTICE</div><h2>Your ${m.short.toLowerCase()} worksheet</h2><p class="save-note">Use non-sensitive practice content. These notes save only in this browser unless you choose to sync them from My workspace.</p>${m.fields.map(f=>field(m,...f)).join('')}${m.id==='review'?rubric():''}${m.id==='prompt'?`<button class="button secondary" data-action="build-prompt">Build a brief from my blueprint ↗</button>${promptLibrary()}`:''}<div class="status-line" data-save-status>${workspace.updatedAt?'Saved in this browser':'Your notes save as you type.'}</div></section><section class="panel"><h3>Before you move on</h3><p>Use these self-checks to log your progress. Check a box when you have completed that task; uncheck it when you need to revisit it.</p><div class="checklist">${m.checks.map((label,i)=>`<label><input type="checkbox" data-check="${id}:${i}" ${workspace.checks[id]?.[i]?'checked':''}><span>${label}</span></label>`).join('')}</div><div class="status-line" id="module-completion">${completed(workspace,id)?'✓ All four self-checks complete.':'Complete all four self-checks to mark this module complete.'}</div><a class="button" href="${next?'#module/'+next.id:'#workspace'}">${next?'Next: '+next.short:'Review my progress'} ↗</a></section></article><aside><div class="side-panel"><h3>YOUR PATHWAY</h3><div class="module-menu">${modules.map(x=>`<a class="${x.id===id?'current':''}" href="#module/${x.id}">${x.number} · ${x.short} ${completed(workspace,x.id)?'✓':''}</a>`).join('')}</div><p>Review and revisit in any order.</p><a class="text-link" href="#workspace">My saved workspace ↗</a></div></aside></div>`;}
function resources(){const query=resourceQuery.toLowerCase();const matching=modules.filter(m=>`${m.title} ${m.short} ${m.subtitle}`.toLowerCase().includes(query));return heading('RESOURCE LIBRARY','Good tools.<br>Better starting points.','The original editable workshop materials, paired with practical examples. Download, adapt to your assessment context, and keep human review in the loop.')+`<label class="field search-box">Find a resource<input id="resource-search" type="search" placeholder="Search blueprint, prompts, rubric…" value="${e(resourceQuery)}"></label><div class="three-col" id="resource-results">${matching.map(m=>`<article class="resource-card"><div class="module-icon ${m.color}" aria-hidden="true">${m.icon}</div><div><span class="tag">EDITABLE DOCX · ${m.number}</span></div><h3 style="margin-top:14px">${m.short==='Expert review'?'Item review rubric':m.short==='AI prompts'?'AI & LLM prompt pack':m.short==='Blueprint'?'Item blueprint mini-template':m.short==='Item metadata'?'Item metadata sheet':'AI-use audit log'}</h3><p>${m.subtitle}</p><div class="button-row">${fileLink(m.file,'Template ↓')}<a class="text-link" href="./downloads/examples/${m.example}" download>Worked example ↓</a></div><a class="text-link" style="margin-top:15px" href="#module/${m.id}">Explore the module ↗</a></article>`).join('')||'<p>No matching resources. Try another search term.</p>'}</div><section class="resource-banner"><div><h3>The complete collection.</h3><p>Two ZIP bundles. Five blank templates and five worked examples.</p></div><div class="button-row"><a class="button secondary" href="./downloads/participant-toolkit.zip" download>Participant toolkit ↓</a><a class="button secondary" href="./downloads/worked-examples.zip" download>Worked examples ↓</a></div></section><section class="panel prose" style="margin-top:24px"><h3>A note on use</h3><p>Workshop materials are provided for participant learning and adaptation within your assessment practice. Do not upload secure operational items or identifiable learner data. © Taiwo Feyijimi. All rights reserved.</p></section>`;}
function workspacePage(){const sync=read('acata.sync.v1',null);return heading('MY WORKSPACE','Your work, taking shape.','Keep your progress and practice notes together. Learning is available without an account. Back up your workspace before clearing browser data or moving devices.')+`<div class="two-col"><section class="panel"><h2>Your pathway</h2>${ring()}<p>${completionCount(workspace)} of 5 modules complete. Progress reflects your own checklist entries.</p><div class="pathway-list">${modules.map(moduleCard).join('')}</div></section><div><section class="panel"><h2>Save a copy. Keep the context.</h2><p>Your worksheet notes, rubric, and checklists are stored on this browser. Export a JSON backup to restore on another device. Your research survey and recovery codes are stored separately.</p><div class="button-row"><button class="button" data-action="export">Export workspace ↓</button><button class="button secondary" data-action="print">Print / save PDF</button></div><div class="divider"></div><label class="field">Restore a workspace backup<input class="file-input" id="import-workspace" type="file" accept="application/json,.json"><span class="field-help">Restoring replaces your current local notes. Export first if you need both copies.</span></label><p class="small">${workspace.updatedAt?'Last saved: '+e(new Date(workspace.updatedAt).toLocaleString()):'No notes saved yet.'}</p></section><section class="panel"><h2>Pick up on another device.</h2><p>Optional cloud sync saves your checklists and practice notes using a private recovery code. Anyone with that code can access your workspace. Keep it safe; there is no email or password reset.</p>${!service.available?'<div class="notice">Cloud sync is not connected yet. Local saving, export, and restore work now.</div>':`<div class="button-row"><button class="button secondary" data-action="${sync?'sync-upload':'sync-create'}">${sync?'Upload local workspace':'Create my recovery code'}</button>${sync?'<button class="button secondary" data-action="sync-download">Restore from cloud</button><button class="text-button" data-action="sync-code">Show recovery code</button>':''}</div><div id="sync-receipt"></div><label class="field" style="margin-top:18px">Have a recovery code?<input id="recovery-code" type="password" autocomplete="off" placeholder="Paste your 64-character code" maxlength="64"></label><button class="button secondary" data-action="sync-connect">Connect and restore workspace</button><div class="status-line" id="sync-status"></div>`}<p class="small">Cloud sync is separate from the research survey and optional visit analytics.</p></section><details><summary>Manage my stored data</summary><div class="details-body"><p>Clearing local notes does not delete an existing cloud copy. Delete the cloud copy first if you want to remove both.</p><div class="button-row"><button class="button secondary" data-action="clear-local">Clear local workspace</button>${sync&&service.available?'<button class="button secondary" data-action="delete-cloud">Delete cloud workspace</button>':''}</div></div></details></div></div>`;}
function likert(id,text,type='confidence'){const draft=surveyDraft[stage]||{};return `<fieldset class="survey-fieldset"><legend>${e(text)}</legend><div class="likert">${[1,2,3,4,5].map(v=>`<label><input type="radio" name="${id}" value="${v}" ${String(draft[id])===String(v)?'checked':''}>${v}</label>`).join('')}<label><input type="radio" name="${id}" value="skip" ${draft[id]==='skip'?'checked':''}>Prefer not to answer</label></div><p class="likert-note">${type==='confidence'?'1 = Not at all confident · 5 = Very confident':'1 = Strongly disagree · 5 = Strongly agree'}</p></fieldset>`;}
function survey(){const draft=surveyDraft[stage]||{},research=service.research||{},enabled=service.available&&research.enabled;return heading('RESEARCH & REFLECTION','What changed?<br>What comes next?','A proposed survey grounded in the workshop: construct alignment, responsible prompting, review, evidence, and human accountability. Participation is separate from access to every learning resource.')+`<div class="research-layout"><article><div class="notice">${enabled?'Research collection is open. Read the study information and consent choices before submitting.':'Survey preview · Research collection is not open. You can explore questions and save a private draft. Nothing here is submitted for research until the study details are confirmed and collection is enabled.'}</div><section class="panel"><div class="eyebrow">STUDY INFORMATION</div><h2>Informed participation, by choice.</h2>${enabled?`<p>${e(research.consentText)}</p><p><strong>Research contact:</strong> ${e(research.contact)}<br><strong>Retention:</strong> ${e(research.retentionDays)} days<br><strong>Study review:</strong> ${e(research.approval)}<br><strong>Consent version:</strong> ${e(research.consentVersion)}</p>`:'<p>This proposed instrument explores changes in workshop knowledge, self-reported confidence, perceived usefulness, and later use in practice. It is an author-developed draft; it has not been established as a validated scale.</p><p>The study lead must confirm the research contact, approved participant information, review status, purpose and use of responses, risks, benefits, retention, and withdrawal arrangements before opening collection.</p>'}<p>Do not include names, email addresses, institution names, identifiable learner information, or secure items in free text. A random study code can pair your responses across stages; it is separate from your workspace recovery code. Responses are pseudonymous, not guaranteed anonymous.</p><p class="small">Estimated completion: 5–8 minutes per stage. You can skip any question. No payment or certification is offered through this survey.</p></section><section class="panel"><h2>Your perspective, at three points.</h2><div class="survey-steps" aria-label="Survey stage">${[['pre','Before the workshop'],['post','After the workshop'],['followup','Later reflection']].map(([id,label])=>`<button data-stage="${id}" class="${stage===id?'selected':''}" aria-pressed="${stage===id}">${label}</button>`).join('')}</div><p>${stage==='pre'?'Complete this before working through the modules, where possible.':stage==='post'?'Reflect after completing the workshop activities.':'Reflect after you have had an opportunity to use the workflow in practice. No fixed follow-up interval was specified in the source materials.'}</p><form id="survey-form"><div class="two-col"><label class="field">Professional role (optional)<select name="role"><option value="">Choose or skip</option>${roleOptions.map(v=>`<option ${draft.role===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Current AI use in item development (optional)<select name="experience"><option value="">Choose or skip</option>${experienceOptions.map(v=>`<option ${draft.experience===v?'selected':''}>${v}</option>`).join('')}</select></label></div><h3>Confidence in practice</h3>${confidenceItems.map(([id,text])=>likert('c_'+id,text)).join('')}<div class="divider"></div><h3>Workshop knowledge</h3><p>Choose the best answer or “Not sure / prefer not to answer”. Responses do not affect access to the workshop.</p>${knowledgeItems.map(k=>`<fieldset class="survey-fieldset"><legend>${e(k.question)}</legend>${k.options.map((label,i)=>`<label class="radio-option"><input type="radio" name="${k.id}" value="${i}" ${String(draft[k.id])===String(i)?'checked':''}>${e(label)}</label>`).join('')}</fieldset>`).join('')}${stage!=='pre'?`<div class="divider"></div><h3>Experience & intended practice</h3>${attitudeItems.map(([id,text])=>likert('a_'+id,text,'attitude')).join('')}`:''}${stage==='followup'?`<label class="field">How often have you used the documented workflow since the workshop?<select name="transfer"><option value="">Choose or skip</option>${['Not yet','Once','A few times','Regularly','Prefer not to say'].map(v=>`<option ${draft.transfer===v?'selected':''}>${v}</option>`).join('')}</select></label>`:''}<label class="field">${stage==='pre'?'What would you most like to gain from this workshop?':stage==='post'?'What changed in your approach? What should we improve?':'What helped or hindered use in your own practice?'} (optional)<textarea name="reflection" maxlength="2000" placeholder="Avoid identifying details and secure assessment content.">${e(draft.reflection||'')}</textarea></label><div class="divider"></div><label class="radio-option"><input type="checkbox" name="consent" ${draft.consent?'checked':''} ${enabled?'':'disabled'}>I have read the study information and voluntarily consent to this stage of the research survey.</label><div class="button-row"><button class="button" type="submit" ${enabled?'':'disabled'}>${enabled?'Submit research response':'Research submission not open'}</button><button class="button secondary" type="button" data-action="survey-export">Export my draft ↓</button><button class="text-button" type="button" data-action="survey-clear">Clear this stage’s local draft</button></div><div class="status-line" id="survey-status" role="status">Draft saves in this browser as you answer.</div></form><div id="survey-receipt"></div></section><section class="panel"><h3>Withdraw a submitted stage</h3><p>Use the deletion code from your submission receipt while identifiable-by-code records are retained. Aggregate findings already released cannot be retracted through this tool.</p><label class="field">Submission deletion code<input type="password" id="deletion-code" autocomplete="off" maxlength="64"></label><button class="button secondary" data-action="survey-withdraw" ${service.available?'':'disabled'}>Delete the submitted response</button><div class="status-line" id="withdraw-status"></div></section></article><aside><div class="side-panel"><h3>WHAT THIS SURVEY EXPLORES</h3><div class="checklist">${['Blueprint confidence','Prompting and review','Knowledge of evidence limits','Human accountability','Transfer into practice'].map(x=>`<div class="small">↗ ${x}</div>`).join('')}</div><p>Self-reported improvement is distinct from demonstrated item quality or validation evidence.</p></div><div class="side-panel"><h3>Your study code</h3><p>Optional pairing across stages and devices. Keep this code private. It does not grant access to other participants’ answers.</p><label class="field">Pairing code<input id="study-code" autocomplete="off" maxlength="48" placeholder="Generate or paste a code" value="${e(read('acata.study.code',''))}"></label><div class="button-row"><button class="button secondary compact" data-action="study-generate">Generate</button><button class="button secondary compact" data-action="study-save">Save code</button></div><p class="small">If you leave this blank when submitting, a random code will be generated for you.</p></div></aside></div>`;}
function example(){return heading('THE WORKED EXAMPLE','One small item.<br>The whole workflow.','The workshop’s secondary science example shows how an item moves from a blueprint to an auditable, provisionally reviewed draft.')+`<div class="two-col"><section class="panel"><div class="eyebrow">OHM-001 · VERSION 1.1</div><h2>Try the practice item.</h2><p>A simple circuit has a voltage of 12 V across a resistor of 4 ohms. What is the current in the circuit?</p><div class="knowledge-options">${['A. 0.33 A','B. 3 A','C. 8 A','D. 48 A'].map((x,i)=>`<button data-example-answer="${i}">${x}</button>`).join('')}</div><div id="example-feedback" role="status"></div><p class="small" style="margin-top:18px">Illustrative practice only. This example is not tied to a particular examination board or national curriculum.</p></section><section class="panel"><h2>What should it measure?</h2><p><strong>Construct:</strong> apply the relationship among voltage, current, and resistance in a simple direct-current circuit.</p><p><strong>Evidence:</strong> select the result of dividing voltage by resistance. The intended process is Apply; the task uses a single resistor and simple arithmetic.</p><p><strong>Scope:</strong> no series or parallel circuits and no diagram required. Check terminology against prior instruction.</p></section></div><div class="panel prose"><h2>Follow the record.</h2><ol><li><strong>Blueprint:</strong> a low-stakes formative check for secondary science learners. Define the outcome and content boundary before generation.</li><li><strong>AI prompt:</strong> request one four-option item, key, rationale, and distractor logic. Keep constraints explicit.</li><li><strong>Review:</strong> independently verify I = V/R = 12/4 = 3 A. Plausible distractor explanations remain hypotheses; the source rates distractor quality and intended difficulty provisionally.</li><li><strong>Metadata:</strong> one point, key B, version 1.1, provisionally ready for pilot consideration. Empirical difficulty and discrimination are unavailable; it is not calibrated for CAT.</li><li><strong>Audit:</strong> record AI contributions and the human verification, including what remains unknown. Retaining the draft does not establish validity or absence of bias.</li></ol><div class="callout warning">Still to investigate: empirical difficulty, discrimination, distractor functioning, differential performance, and other evidence appropriate to the assessment purpose and sample.</div><a class="button secondary" href="./downloads/worked-examples.zip" download>Download all five worked records ↓</a></div>`;}
function dashboard(){return heading('FACILITATOR SPACE','Insight, with context.','A private view of recorded visits, approximate visitor countries, module completion from synced workspaces, and research submissions.')+(!service.available?`<section class="panel"><h2>The data service is not connected.</h2><p>No analytics numbers are fabricated here. Connect the supplied backend to see recorded visits and country-level reach. Local participant notes remain available independently.</p><a class="button secondary" href="#home">Return to the workshop ↗</a></section>`:!dashboardToken?`<section class="panel" style="max-width:550px"><h2>Facilitator sign-in</h2><p>Use your private administrator access token. It stays in memory for this page session and is never saved in browser storage or included in the public website configuration.</p><form id="admin-login"><label class="field">Administrator access token<input id="admin-token" type="password" required autocomplete="off"></label><button class="button">Open dashboard ↗</button><div class="status-line" id="admin-status" role="status"></div></form></section>`:stats?renderStats():`<div class="panel">Loading recorded analytics…</div>`);}
function renderStats(){return `<div class="button-row" style="margin-bottom:22px"><button class="button secondary compact" data-action="refresh-stats">Refresh</button><button class="button secondary compact" data-action="export-stats">Export analytics CSV ↓</button><button class="button secondary compact" data-action="export-research">Export research CSV ↓</button><button class="text-button" data-action="admin-logout">Sign out</button></div><p class="small">Updated ${e(new Date(stats.generatedAt).toLocaleString())}. UTC dates. Rolling 30-day analytics; synced workspaces and retained research responses shown separately.</p><div class="dashboard-metrics">${[['Page views',stats.views],['Visitor-days',stats.visitorDays],['Countries',stats.countries.filter(c=>c.country!=='XX').length],['Research responses',stats.responses]].map(([label,value])=>`<div class="metric"><span>${label}</span><strong>${Number(value)||0}</strong><span>Recorded data only</span></div>`).join('')}</div><div class="two-col"><section class="panel"><h2>Visits over time</h2>${stats.daily.length?`<div class="chart" aria-label="Page views by day">${stats.daily.map(d=>`<div class="chart-column" title="${e(d.day)}: ${d.views} views"><small>${d.views}</small><div class="chart-bar" style="height:${Math.max(2,d.views/Math.max(...stats.daily.map(d=>d.views))*130)}px"></div><small>${e(d.day.slice(5))}</small></div>`).join('')}</div><div class="table-scroll"><table><caption>Daily page views and visitor-days</caption><thead><tr><th>Date (UTC)</th><th>Views</th><th>Visitor-days</th></tr></thead><tbody>${stats.daily.map(d=>`<tr><td>${e(d.day)}</td><td>${d.views}</td><td>${d.visitors}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No opted-in visits recorded in this period.</div>'}</section><section class="panel"><h2>Where visits come from</h2><p>Approximate country from the network connection. VPNs and provider coverage can affect accuracy. These are page views, not confirmed participant locations.</p>${stats.countries.length?stats.countries.map(c=>`<div style="margin:16px 0"><div class="button-row" style="justify-content:space-between"><span>${e(countryName(c.country))}</span><small>${c.views} views</small></div><div class="country-bar"><span style="width:${Math.round(c.views/Math.max(1,stats.views)*100)}%"></span></div></div>`).join(''):'<div class="empty-state">Country data appears after consented visits.</div>'}</section></div><div class="two-col"><section class="panel"><h2>Workshop progress</h2><p>Based only on participants who explicitly synced a workspace. Checklists are self-reported, not a learning assessment.</p><table><caption>${stats.participants} synced workspaces currently retained</caption><thead><tr><th>Module</th><th>Complete</th></tr></thead><tbody>${modules.map(m=>`<tr><th scope="row">${m.short}</th><td>${stats.completion[m.id]||0}</td></tr>`).join('')}</tbody></table></section><section class="panel"><h2>Survey participation</h2><p>Counts by stage. A response is not necessarily a distinct person. The research export contains the author-developed instrument version and consent record.</p><table><thead><tr><th>Stage</th><th>Responses</th></tr></thead><tbody>${stages.map(s=>`<tr><th scope="row">${s==='pre'?'Before':s==='post'?'After':'Later reflection'}</th><td>${stats.surveyStages[s]||0}</td></tr>`).join('')}</tbody></table></section></div><div class="callout">“Visitor-days” counts a returning visitor again on a different UTC day. Opt-outs, blockers, retries, shared devices, and automation can affect these counts. Analytics do not identify a person or measure workshop impact.</div>`;}
function countryName(code){try{return code==='XX'?'Unknown / unavailable':new Intl.DisplayNames(['en'],{type:'region'}).of(code)||code;}catch{return code;}}
function privacy(){return heading('PRIVACY & DATA','Useful learning.<br>Considerate data practices.','Your workspace, optional analytics, and voluntary research are separate. You can use the learning materials without joining a study or allowing visit analytics.')+`<article class="panel prose"><h2>Workspace storage</h2><p>Your checklists, notes, and rubric save in local browser storage. Other people who use this browser profile can read them. Clearing browser data removes them; export a backup first. No secure operational test content, identifying learner data, or confidential material should be entered.</p><p>Optional cloud sync sends only the workspace you choose to upload. A randomly generated recovery code grants access to that copy. The application stores a hash of the code on the server. A lost code cannot be recovered. Use My workspace to delete the server copy; clearing local notes alone does not delete it.</p><h2>Optional visit analytics</h2><p>Visit analytics are off until you allow them in Analytics preferences. When connected, the service records a page identifier, UTC day, approximate country, and a hashed daily visitor identifier. The application database does not store IP addresses, precise geolocation, full user-agent strings, full referral URLs, or your notes with these events. No browser geolocation permission is requested. The service uses a short-lived keyed hash of connection address, route, and hour for anti-abuse limits; plaintext addresses are not retained in those buckets.</p><p>A random visitor identifier rotates daily. It is separate from research and workspace credentials. Country is inferred by the backend hosting provider and can be inaccurate. Opting out stops future events and clears this browser’s visitor identifier. Analytics records are configured for deletion after 90 days; deletion requires the deployed daily scheduled task.</p><h2>Research survey</h2><p>${service.research?.enabled?'Collection is enabled; the survey page displays the current study information and contact.':'Research submission is currently disabled pending study details. Private survey drafts remain in this browser and can be exported or cleared.'} The draft instrument includes role, AI-use frequency, six confidence items, five knowledge items, post-workshop attitudes, an optional reflection, and later transfer into practice. It is not a validated scale.</p><p>When collection is enabled, the application sends only survey responses, stage, instrument and consent versions, a random hashed pairing code, and a receipt deletion-code hash. It does not attach your workspace code or analytics identifier. Free text or unusual combinations can still identify someone, so responses are described as pseudonymous.</p><p>Keep the deletion code in your submission receipt. It allows deletion of that submitted stage during the retention period. The service does not provide a public participant response directory. Aggregate findings already released cannot be withdrawn through this interface.</p><h2>Services and access</h2><p>The public frontend is prepared for GitHub Pages. The shared data service is prepared for Cloudflare Workers and D1. Hosting providers process connection information according to their own terms; this notice describes the application database, not all provider logs. The facilitator dashboard and research exports require a private administrator token.</p><h2>Your choices</h2><p>Use Analytics preferences below to allow or stop analytics. Manage local and cloud workspace copies under My workspace. Survey drafts can be cleared independently, and submitted responses can be deleted with their receipt code.</p><div class="button-row"><button class="button secondary" data-action="preferences">Analytics preferences</button><a class="button secondary" href="#workspace">Manage workspace</a><a class="button secondary" href="#survey">Survey choices</a></div><h2>Copyright</h2><p>© ${new Date().getFullYear()} Taiwo Feyijimi. All rights reserved. Workshop templates are provided for participant learning and adaptation in assessment practice. Contact the copyright holder for wider redistribution, publication, or commercial reuse.</p></article>`;}
function about(){return heading('ABOUT THE WORKSHOP','Human judgment.<br>AI assistance.','Modernising Item Development with AI and LLMs · ACATA 2026 Hands-On Workshop.')+`<section class="about-card"><div class="eyebrow">YOUR FACILITATOR</div><h2>Taiwo Feyijimi</h2><p>A practical learning space built around thoughtful item design, independent review, and transparent professional decisions.</p></section><div class="panel prose" style="margin-top:24px"><h2>Built from the workshop materials</h2><p>This site follows the five supplied participant documents: the Item Blueprint Mini-Template, AI & LLM Prompt Pack, Item Review Rubric, Item Metadata Sheet, and AI-Use Audit Log. Each stage is paired with the supplied minimal worked example for secondary science and Ohm’s law.</p><p>The learning pathway summarises the documents; the editable downloads retain the source detail. Suggested site activities and the proposed research survey extend the materials and are not presented as original workshop findings.</p><h2>Return whenever you need</h2><p>Use this space to revisit a prompt, document a review, or work through a fresh practice example. Progress is self-reported; completing the pathway is not a certification, item validation, or calibration.</p><div class="button-row"><a class="button" href="#learn">Explore the pathway ↗</a><a class="button secondary" href="${config.repository}" target="_blank" rel="noopener">GitHub repository ↗</a></div><p class="small" style="margin-top:20px">© ${new Date().getFullYear()} Taiwo Feyijimi. All rights reserved.</p></div>`;}
function notFound(){return heading('PAGE NOT FOUND','Let’s find your place.','This workshop page could not be found.')+'<a class="button" href="#home">Back to overview ↗</a>';}

function route(){
 const parts=location.hash.slice(1).split('/'),page=parts[0]||'home';
 const routes={home,learn,resources,workspace:workspacePage,survey,example,dashboard,privacy,about};
 view.innerHTML=page==='module'?modulePage(parts[1]):(routes[page]||notFound)();
 if(page==='survey'&&read('acata.survey.receipt.'+stage,null))$('#survey-receipt').innerHTML='<div class="callout">A submission receipt for this stage is saved in this browser. <button class="text-button" data-action="receipt-show">Show my saved receipt</button></div>';
 const active=page==='module'||page==='example'?'learn':page;
 $$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===active);if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 const labels={home:'Overview',learn:'Learning pathway',resources:'Resource library',workspace:'My workspace',survey:'Research survey',dashboard:'Facilitator dashboard',privacy:'Privacy & data',about:'About',example:'Worked example',module:modules.find(m=>m.id===parts[1])?.short||'Module'};
 $('#page-label').textContent=labels[page]||'Page not found';
 document.title=`${labels[page]||'Workshop'} · ACATA 2026`;
 $('#year').textContent=new Date().getFullYear();
 if(!storageAvailable)view.insertAdjacentHTML('afterbegin','<div class="notice">Browser storage is unavailable. Keep a workspace export before leaving.</div>');
 recordVisit(page==='module'?`module/${parts[1]}`:page);
}
async function recordVisit(page){
 if(read('acata.analytics.choice',null)!=='allow'||!service.available||document.visibilityState==='hidden'||analyticsSent.has(page))return;
 const day=new Date().toISOString().slice(0,10);let visitor=read('acata.analytics.visitor',null);
 if(visitor?.day!==day){visitor={day,id:uid()};store('acata.analytics.visitor',visitor);}
 const event={page,eventId:uid(),visitorId:visitor.id};analyticsSent.add(page);
 try{await api('/visit',{method:'POST',body:event});}catch{analyticsSent.delete(page);}
}
async function clipboard(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{toast('Clipboard access is unavailable. Select and copy the text directly.');}}
function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportWorkspace(){download('acata-workspace-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(workspace,null,2));toast('Workspace backup exported. Keep it private.');}
function printWorkspace(){
 $('#print-report')?.remove();const report=document.createElement('article');report.id='print-report';
 report.innerHTML=`<h1>My ACATA 2026 workspace</h1><p>Self-reported learning record · ${e(new Date().toLocaleDateString())}<br>© Taiwo Feyijimi. All rights reserved.</p>${modules.map(m=>`<section><h2>${m.number}. ${m.title}</h2><p>${completed(workspace,m.id)?'Complete':'In progress'} · self-checks</p><ul>${m.checks.map((label,i)=>`<li>${workspace.checks[m.id]?.[i]?'[✓]':'[ ]'} ${label}</li>`).join('')}</ul>${m.fields.map(([key,label])=>`<h3>${label}</h3><div class="report-entry">${e(workspace.fields[m.id]?.[key]||'No notes recorded.')}</div>`).join('')}${m.id==='review'?`<table><caption>Item review evidence</caption><thead><tr><th>Criterion</th><th>Rating</th><th>Evidence</th></tr></thead><tbody>${criteria.map(([name],i)=>`<tr><th>${name}</th><td>${e(workspace.rubric[i]?.rating||'Not rated')}</td><td>${e(workspace.rubric[i]?.evidence||'')}</td></tr>`).join('')}</tbody></table><h3>Disposition</h3><p>${e(workspace.disposition||'Not recorded')}</p><div class="report-entry">${e(workspace.reviewSummary)}</div>`:''}</section>`).join('')}`;
 $('#main').append(report);document.body.classList.add('printing-workspace');window.print();
}
function syncReceipt(code){$('#sync-receipt').innerHTML=`<p class="small">Private recovery code · save outside this browser</p><div class="receipt">${e(code)}</div><button class="text-button" style="margin-top:8px" data-action="copy-sync-code">Copy recovery code</button>`;}
async function syncAction(action){
 const sync=read('acata.sync.v1',null);
 if(action==='sync-create'){
  const data=await api('/participant',{method:'POST',body:{workspace}});store('acata.sync.v1',{token:data.token,revision:data.revision});route();syncReceipt(data.token);toast('Cloud workspace created. Save your recovery code.');
 }else if(action==='sync-upload'){
  const data=await api('/progress',{method:'PUT',token:sync.token,body:{workspace,revision:sync.revision}});store('acata.sync.v1',{...sync,revision:data.revision});toast('Current workspace uploaded.');
 }else if(action==='sync-download'||action==='sync-connect'){
  const token=action==='sync-connect'?$('#recovery-code').value.trim():sync.token;
  if(!/^[a-f0-9]{64}$/.test(token))throw new Error('Enter a valid 64-character recovery code.');
  if(!confirm('Replace the notes in this browser with the cloud workspace? Export a local backup first if needed.'))return;
  const data=await api('/progress',{token});workspace=validateWorkspace(data.workspace);save();store('acata.sync.v1',{token,revision:data.revision});route();toast('Cloud workspace restored.');
 }else if(action==='sync-code')syncReceipt(sync.token);
 else if(action==='copy-sync-code')await clipboard(sync.token);
 else if(action==='delete-cloud'){
  if(!confirm('Permanently delete your cloud workspace? Your local notes will remain.'))return;
  await api('/progress',{method:'DELETE',token:sync.token});localStorage.removeItem('acata.sync.v1');route();toast('Cloud workspace deleted.');
 }
}
async function refreshStats(){stats=await api('/admin/stats',{token:dashboardToken});route();}
async function adminExport(kind){const data=await api('/admin/export?kind='+kind,{token:dashboardToken});download(`acata-${kind}-${new Date().toISOString().slice(0,10)}.csv`,data.csv,'text/csv;charset=utf-8');toast('Private export downloaded. Store it securely.');}
function draftFromForm(){const form=$('#survey-form');if(!form)return;const data=Object.fromEntries(new FormData(form));data.consent=Boolean(form.elements.consent.checked);surveyDraft[stage]=data;store('acata.survey.draft.v1',surveyDraft);}
async function submitSurvey(form){
 draftFromForm();if(!service.research?.enabled)throw new Error('Research collection is not open.');
 if(!form.elements.consent.checked)throw new Error('Voluntary consent is required to submit a research response.');
 let code=read('acata.study.code','');if(!code){code=uid();store('acata.study.code',code);}
 const answers={...surveyDraft[stage]};delete answers.consent;
 const pendingKey='acata.survey.pending.'+stage;let pending=read(pendingKey,null);
 if(!pending){pending={submissionId:uid(),deletionCode:uid()+uid().slice(0,16)};store(pendingKey,pending);}
 const result=await api('/survey',{method:'POST',body:{...pending,studyCode:code,stage,instrumentVersion:surveyVersion,consentVersion:service.research.consentVersion,consent:true,answers}});
 const receipt={stage,submissionId:result.submissionId,deletionCode:pending.deletionCode,submittedAt:result.submittedAt};
 store('acata.survey.receipt.'+stage,receipt);localStorage.removeItem(pendingKey);
 $('#survey-receipt').innerHTML=`<div class="completion"><h3>Your response was received.</h3><p>Save this private receipt. Its deletion code lets you withdraw this stage while the record is retained.</p><div class="receipt">Stage: ${e(stage)}<br>Deletion code: ${e(receipt.deletionCode)}<br>Study pairing code: ${e(code)}</div><button class="button secondary compact" style="margin-top:12px" data-action="receipt-download">Download receipt ↓</button></div>`;
 $('#survey-status').textContent='Submitted successfully. Repeating this stage with the same study code is prevented by the service.';
}

document.addEventListener('input',event=>{
 const el=event.target;
 if(el.dataset.field){const [id,key]=el.dataset.field.split(':');workspace.fields[id]??={};workspace.fields[id][key]=el.value;save();}
 if(el.dataset.rubric){const [index,key]=el.dataset.rubric.split(':');while(workspace.rubric.length<=Number(index))workspace.rubric.push({rating:'',evidence:''});workspace.rubric[index][key]=el.value;save();}
 if(el.dataset.workspace){workspace[el.dataset.workspace]=el.value;save();}
 if(el.closest('#survey-form')){clearTimeout(saveTimer);saveTimer=setTimeout(draftFromForm,150);}
 if(el.id==='resource-search'){resourceQuery=el.value;const start=el.selectionStart;view.innerHTML=resources();const input=$('#resource-search');input.focus();input.setSelectionRange(start,start);}
});
document.addEventListener('change',async event=>{
 const el=event.target;
 if(el.dataset.check){const[id,index]=el.dataset.check.split(':');workspace.checks[id]??=[false,false,false,false];workspace.checks[id][index]=el.checked;save();$('#module-completion').textContent=completed(workspace,id)?'✓ All four self-checks complete.':'Complete all four self-checks to mark this module complete.';}
 if(el.id==='import-workspace'&&el.files?.[0]){
  try{const file=el.files[0];if(file.size>500000)throw new Error('The backup is too large. Choose an ACATA JSON workspace under 500 KB.');const parsed=validateWorkspace(JSON.parse(await file.text()));if(!confirm('Replace your local workspace with this backup?')){el.value='';return;}workspace=parsed;save();route();toast('Workspace restored.');}catch(error){toast(error.message);el.value='';}
 }
});
document.addEventListener('click',async event=>{
 const el=event.target.closest('button,a');if(!el)return;
 if(el.classList.contains('skip-link')){event.preventDefault();$('#main').focus();return;}
 try{
  if(el.dataset.stage){draftFromForm();stage=el.dataset.stage;route();return;}
  if(el.dataset.copyPrompt){const prompt=prompts.find(p=>p.number===Number(el.dataset.copyPrompt));await clipboard(prompt.body);return;}
  if(el.dataset.exampleAnswer){$$('[data-example-answer]').forEach(b=>b.classList.toggle('selected',b===el));const correct=el.dataset.exampleAnswer==='1';$('#example-feedback').innerHTML=`<div class="answer-feedback"><strong>${correct?'Correct.':'Revisit the relationship.'}</strong> I = V/R = 12/4 = 3 A, so B is the key. The other options illustrate possible reversal (0.33), subtraction (8), and multiplication (48). Those error explanations remain hypotheses until reviewed or supported by learner data.</div>`;return;}
  const action=el.dataset.action;if(!action)return;
  if(action.startsWith('sync-')||action==='copy-sync-code'||action==='delete-cloud'){el.disabled=true;try{await syncAction(action);}finally{el.disabled=false;}return;}
  if(action==='export')exportWorkspace();
  if(action==='print')printWorkspace();
  if(action==='preferences')$('#preferences').showModal();
  if(action==='clear-local'&&confirm('Clear this browser’s workspace notes and checklists? Export a backup first if needed.')){workspace=emptyWorkspace();save();route();toast('Local workspace cleared.');}
  if(action==='build-prompt'){
   const b=workspace.fields.blueprint||{};const brief=`You are supporting an assessment development team. Use the following blueprint as binding constraints. Flag missing information rather than inventing it.\n\nASSESSMENT CONTEXT\n${b.context||'[INSERT CONTEXT]'}\nCONSTRUCT, OUTCOME AND EVIDENCE\n${b.construct||'[INSERT CONSTRUCT AND EVIDENCE]'}\nCOGNITIVE DEMAND\n${b.cognition||'[INSERT COGNITIVE PROCESS]'}\nCONTENT BOUNDARIES\n${b.boundaries||'[INSERT BOUNDARIES]'}\nITEM DESIGN\n${b.format||'[INSERT FORMAT AND COVERAGE]'}\nFAIRNESS AND ACCESSIBILITY\n${b.fairness||'[INSERT CONSTRAINTS]'}\n\nReturn a draft item, key/scoring guidance, rationale, distractor error pathways where applicable, alignment, cognitive-demand justification, provisional difficulty rationale, and uncertainty or fairness concerns. Do not claim empirical difficulty, validity, reliability, or absence of bias. A human reviewer must verify technical content and scoring before pilot consideration.`;
   workspace.fields.prompt??={};workspace.fields.prompt.brief=brief;save();$('[data-field="prompt:brief"]').value=brief;toast('Brief built from your current blueprint. Fill all missing fields.');
  }
  if(action==='survey-export'){draftFromForm();download('acata-survey-draft-'+stage+'.json',JSON.stringify({instrumentVersion:surveyVersion,stage,answers:surveyDraft[stage],notice:'Private draft. This file has not been submitted for research.'},null,2));}
  if(action==='survey-clear'&&confirm('Clear this stage’s local survey draft? Submitted responses are managed separately with a deletion code.')){delete surveyDraft[stage];store('acata.survey.draft.v1',surveyDraft);route();}
  if(action==='study-generate'){if(read('acata.study.code','')&&!confirm('Replace your study pairing code? A new code will not link to earlier stages.'))return;const code=uid();store('acata.study.code',code);$('#study-code').value=code;toast('Study pairing code saved in this browser.');}
  if(action==='study-save'){const code=$('#study-code').value.trim();if(!/^[a-f0-9]{48}$/.test(code))throw new Error('Use a generated 48-character study code.');store('acata.study.code',code);toast('Study pairing code saved.');}
  if(action==='receipt-download'){const receipt=read('acata.survey.receipt.'+stage,null);if(receipt)download('acata-research-receipt-'+stage+'.json',JSON.stringify({...receipt,studyCode:read('acata.study.code','')},null,2));}
  if(action==='receipt-show'){const receipt=read('acata.survey.receipt.'+stage,null);if(receipt)$('#survey-receipt').innerHTML=`<div class="completion"><h3>Your saved submission receipt</h3><p>Keep this code private. It lets you delete that stage’s submitted response while retained.</p><div class="receipt">Stage: ${e(receipt.stage)}<br>Submitted: ${e(receipt.submittedAt)}<br>Deletion code: ${e(receipt.deletionCode)}</div><button class="button secondary compact" style="margin-top:12px" data-action="receipt-download">Download receipt ↓</button></div>`;}
  if(action==='survey-withdraw'){const code=$('#deletion-code').value.trim();if(!/^[a-f0-9]{64}$/.test(code))throw new Error('Enter the 64-character deletion code from your receipt.');if(!confirm('Permanently delete the submitted response linked to this code?'))return;await api('/survey',{method:'DELETE',token:code});$('#withdraw-status').textContent='The response has been deleted, or no matching record remains.';$('#deletion-code').value='';}
  if(action==='admin-logout'){dashboardToken='';stats=null;route();}
  if(action==='refresh-stats')await refreshStats();
  if(action==='export-stats')await adminExport('analytics');
  if(action==='export-research')await adminExport('research');
 }catch(error){toast(error.message);}
});
document.addEventListener('submit',async event=>{
 if(!['admin-login','survey-form'].includes(event.target.id))return;event.preventDefault();const form=event.target,button=$('button[type="submit"],button:not([type])',form);if(button)button.disabled=true;
 try{if(form.id==='admin-login'){const candidate=$('#admin-token').value;stats=await api('/admin/stats',{token:candidate});dashboardToken=candidate;route();}else await submitSurvey(form);}catch(error){const status=form.id==='admin-login'?$('#admin-status'):$('#survey-status');if(status)status.textContent=error.message;toast(error.message);}finally{if(button)button.disabled=false;}
});
$('#preferences-button').addEventListener('click',()=>$('#preferences').showModal());
$('#analytics-accept').addEventListener('click',()=>{store('acata.analytics.choice','allow');recordVisit((location.hash.slice(1)||'home'));toast('Visit analytics allowed. You can change this anytime.');});
$('#analytics-decline').addEventListener('click',()=>{store('acata.analytics.choice','decline');localStorage.removeItem('acata.analytics.visitor');toast('Using essential storage only.');});
window.addEventListener('hashchange',()=>{clearTimeout(saveTimer);draftFromForm();route();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){save();draftFromForm();}});
window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-workspace');$('#print-report')?.remove();});
route();
try{prompts=await fetch('./prompts.json').then(r=>{if(!r.ok)throw new Error();return r.json();});if(location.hash==='#module/prompt')route();}catch{}
if(apiBase&&originAllowed){try{service=await api('/config');service.available=true;draftFromForm();route();}catch{service.available=false;}}
if(read('acata.analytics.choice',null)===null&&service.available)setTimeout(()=>$('#preferences').showModal(),1200);
